CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE COLLATE NOCASE, salt TEXT NOT NULL, hash TEXT NOT NULL, iters INTEGER NOT NULL DEFAULT 100000, created INTEGER NOT NULL, c TEXT, agreed INTEGER NOT NULL DEFAULT 0, bet INTEGER NOT NULL DEFAULT 2, tk INTEGER NOT NULL DEFAULT 10, best_hay INTEGER NOT NULL DEFAULT 0, best_dash INTEGER NOT NULL DEFAULT 0, role TEXT NOT NULL DEFAULT 'player', banned INTEGER NOT NULL DEFAULT 0, muted INTEGER NOT NULL DEFAULT 0, CHECK (tk >= 0));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, uid INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (k TEXT PRIMARY KEY, n INTEGER NOT NULL, since INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS timers (uid INTEGER NOT NULL, k TEXT NOT NULL, t INTEGER NOT NULL, PRIMARY KEY (uid, k));
CREATE TABLE IF NOT EXISTS ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, uid INTEGER NOT NULL, delta INTEGER NOT NULL, reason TEXT NOT NULL, t INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_uid ON sessions(uid);
CREATE TABLE IF NOT EXISTS arena (uid INTEGER PRIMARY KEY, xp INTEGER NOT NULL DEFAULT 0, best INTEGER NOT NULL DEFAULT 0, wk TEXT NOT NULL DEFAULT '', wk_best INTEGER NOT NULL DEFAULT 0, played INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, streak INTEGER NOT NULL DEFAULT 0, last_day TEXT NOT NULL DEFAULT '', earn_day TEXT NOT NULL DEFAULT '', earned INTEGER NOT NULL DEFAULT 0, color TEXT NOT NULL DEFAULT 'blue');
CREATE TABLE IF NOT EXISTS bowl (uid INTEGER PRIMARY KEY, best INTEGER NOT NULL DEFAULT 0, wk TEXT NOT NULL DEFAULT '', wk_best INTEGER NOT NULL DEFAULT 0, games INTEGER NOT NULL DEFAULT 0, strikes INTEGER NOT NULL DEFAULT 0, last_day TEXT NOT NULL DEFAULT '', earn_day TEXT NOT NULL DEFAULT '', earned INTEGER NOT NULL DEFAULT 0);
